def norm(pts):
 q=np.array(pts); q=q-q.min(0); return tuple(sorted(map(tuple,q.tolist())))
def variants(shape):
 pts=np.array(shape)
 out=set()
 for k in range(4):
  p=np.rot90(pts,k) if pts.ndim==2 and pts.shape[1]==2 else None
  # use vector transform
  q=pts.copy()
  for _ in range(k): q=np.stack([q[:,1],-q[:,0]],axis=1)
  for flip in [False,True]:
   z=q.copy(); z[:,0]*=(-1 if flip else 1); out.add(norm(z))
 return out
def subset(small,large):
 svars=variants(norm(small)); lset=set(map(tuple,large.tolist()))
 for shp in svars:
  ar=np.array(shp); h,w=ar.max(0)+1
  for r in range(int(large[:,0].min()),int(large[:,0].max())-h+2):
   for c in range(int(large[:,1].min()),int(large[:,1].max())-w+2):
    cand={ (r+int(y),c+int(x)) for y,x in shp }
    if cand<=lset: return True
 return False
